530	int forest_collect_topn(const Forest* f, const float* qvec,
531	                        int top_n, int query_depth,
532	                        const roaring_bitmap_t* allowed,
533	                        int32_t* out_ids, int32_t* out_votes) {
534	    if (top_n <= 0) return 0;
535	    int nt = f->n_trees;
536	    int use_sub = (f->sub_dim > 0 && f->sub_dim < f->dim);
537	    int sd = use_sub ? f->sub_dim : f->dim;
538	
539	    /* Compose effective filter: (allowed AND NOT tombstones).
540	       If no tombstones, effective == allowed; if no caller filter but we
541	       have tombstones, effective = NOT tombstones (flipped over corpus).  */
542	    const roaring_bitmap_t* effective = allowed;
543	    roaring_bitmap_t* composed = NULL;
544	    if (f->tombstones && roaring_bitmap_get_cardinality(f->tombstones) > 0) {
545	        if (allowed) {
546	            composed = roaring_bitmap_andnot(allowed, f->tombstones);
547	        } else {
548	            composed = roaring_bitmap_flip(f->tombstones, 0,
549	                                           (uint64_t)f->n_docs);
550	        }
551	        effective = composed;
552	    }
553	    allowed = effective;
554	
555	    /* Default query_depth to build depth (native query). */
556	    int qd = (query_depth > 0 && query_depth <= f->depth) ? query_depth : f->depth;
557	    int k_shift = f->depth - qd;   /* range size at build depth = 1 << k_shift */
558	
559	    /* Small per-query scratch (cheap). */
560	    float v0[1024], v1[1024];
561	    float qn[1024];
562	    int   dims[256];
563	    if (sd > 1024 || f->dim > 1024 || (use_sub && f->sub_dim > 256)) {
564	        fprintf(stderr, "dim too large for stack scratch\n");
565	        return -1;
566	    }
567	    memcpy(qn, qvec, (size_t)f->dim * sizeof(float));
568	    normalize(qn, f->dim);
569	
570	    /* Persistent scratch from Forest. */
571	    Forest* fm = (Forest*)f;
572	    SparseEntry* wbuf      = (SparseEntry*)fm->wbuf;
573	    uint32_t*    wlen      = fm->wlen_buf;     /* size 2*nt: slot 0=low, 1=high */
574	    uint64_t*    woff      = fm->woff_buf;
575	    int32_t*     leaves    = fm->leaves_buf;
576	    uint32_t*    lens      = fm->lens_buf;
577	    uint64_t*    data_off  = fm->data_off_buf;
578	    uint32_t*    buf_pos   = fm->buf_pos_buf;
579	    TCursor*     cursors   = (TCursor*) fm->cursors_buf;
580	    TCursor**    heap      = (TCursor**)fm->heap_buf;
581	    uint32_t     window_n  = fm->max_window_n;
582	
583	    if (fm->topn_h_cap < top_n) {
584	        free(fm->topn_h_buf);
585	        fm->topn_h_buf = malloc((size_t)top_n * sizeof(IdVote));
586	        fm->topn_h_cap = top_n;
587	    }
588	    IdVote* topn_h = (IdVote*)fm->topn_h_buf;
589	
590	    /* Traverse each tree to query_depth — unless the caller provided
591	       pre-computed leaves (privacy mode : client-side traversal). */
592	    int32_t base_q = leaf_base(qd);
593	    if (g_external_leaves != NULL && g_external_leaves_count >= nt) {
594	        for (int t = 0; t < nt; t++) leaves[t] = g_external_leaves[t];
595	    } else {
596	        for (int t = 0; t < nt; t++) {
597	            int32_t leaf = use_sub
598	                ? traverse_sub(qn, f->dim, f->sub_dim, qd, tree_seed(t),
599	                               v0, v1, dims)
600	                : traverse(qn, f->dim, qd, tree_seed(t), v0, v1);
601	            leaves[t] = leaf - base_q;
602	        }
603	    }
604	
605	    /* Phase 1: per tree, read two windows of sparse_index — one covering
606	       the bucket for low_leaf, one for high_leaf. When buckets coincide
607	       we'd be reading the same range twice — accepted overhead.          */
608	    struct io_uring* ring = (struct io_uring*)&f->ring;
609	    int phase1_submits = 0;
610	    for (int t = 0; t < nt; t++) {
611	        const SortedStore* s = &f->stores[t];
612	        uint32_t low_leaf  = (uint32_t)leaves[t] << k_shift;
613	        uint32_t high_leaf = ((uint32_t)leaves[t] + 1u) << k_shift;
614	        uint32_t stride = s->sample_stride;
615	
616	        for (int slot = 0; slot < 2; slot++) {
617	            uint32_t target  = (slot == 0) ? low_leaf : high_leaf;
618	            size_t   idx     = (size_t)t * 2 + slot;
619	            wlen[idx] = 0; woff[idx] = 0;
620	            if (s->n_nonempty == 0) continue;
621	            uint32_t bucket = sorted_sample_bucket(s, target);
622	            uint32_t start_pos = bucket * stride;
623	            if (start_pos >= s->n_nonempty) continue;
624	            uint32_t take = stride + 1;
625	            if (start_pos + take > s->n_nonempty + 1)
626	                take = s->n_nonempty + 1 - start_pos;
627	            wlen[idx] = take;
628	            woff[idx] = s->index_base + (uint64_t)start_pos * SRT_INDEX_ENTRY;
629	
630	            if (f->ring_ok) {
631	                struct io_uring_sqe* sqe = io_uring_get_sqe(ring);
632	                if (!sqe) { io_uring_submit(ring); sqe = io_uring_get_sqe(ring); }
633	                io_uring_prep_read(sqe, s->fd,
634	                                   wbuf + idx * window_n,
635	                                   (unsigned)(take * SRT_INDEX_ENTRY),
636	                                   (uint64_t)woff[idx]);
637	                io_uring_sqe_set_data(sqe, (void*)(uintptr_t)idx);
638	                phase1_submits++;
639	            } else {
640	                ssize_t pr1 = pread(s->fd, wbuf + idx * window_n,
641	                                    take * SRT_INDEX_ENTRY, (off_t)woff[idx]);
642	                (void)pr1;
643	            }
644	        }
645	    }
646	    if (f->ring_ok) {
647	        io_uring_submit(ring);
648	        for (int r = 0; r < phase1_submits; r++) {
649	            struct io_uring_cqe* cqe;
650	            if (io_uring_wait_cqe(ring, &cqe) < 0) continue;
651	            io_uring_cqe_seen(ring, cqe);
652	        }
653	    }
654	
655	    /* Resolve (start, end) offsets per tree via two lower-bound searches.
656	       SRT3 (delta-VarByte): offsets in `data_off` and lengths in `lens`
657	       refer to BYTES during phase 2; `lens` becomes decoded doc count after.
658	       SRT2 (legacy uint32): offsets/lengths in DOCS; data_off pre-multiplied. */
659	    int is_v3 = (f->srt_version == 3);
660	    uint64_t total_bytes = 0;     /* SRT3 only */
661	    uint64_t total_docs_unit = 0; /* SRT2: docs total; SRT3: same as bytes (upper bound) */
662	    for (int t = 0; t < nt; t++) {
663	        lens[t] = 0; data_off[t] = 0;
664	        buf_pos[t] = is_v3 ? (uint32_t)total_bytes : (uint32_t)total_docs_unit;
665	        const SortedStore* s = &f->stores[t];
666	        if (s->n_nonempty == 0) continue;
667	        uint32_t low_leaf  = (uint32_t)leaves[t] << k_shift;
668	        uint32_t high_leaf = ((uint32_t)leaves[t] + 1u) << k_shift;
669	
670	        const SparseEntry* low_w  = wbuf + ((size_t)t * 2 + 0) * window_n;
671	        const SparseEntry* high_w = wbuf + ((size_t)t * 2 + 1) * window_n;
672	        uint32_t low_len  = wlen[(size_t)t * 2 + 0];
673	        uint32_t high_len = wlen[(size_t)t * 2 + 1];
674	        if (low_len == 0 || high_len == 0) continue;
675	
676	        uint32_t i_lo = lb_in_window(low_w,  low_len,  low_leaf);
677	        uint32_t i_hi = lb_in_window(high_w, high_len, high_leaf);
678	        if (i_lo >= low_len)  continue;
679	        uint32_t start = low_w[i_lo].offset;

679	        uint32_t start = low_w[i_lo].offset;
680	        uint32_t end   = (i_hi < high_len) ? high_w[i_hi].offset
681	                                           : (is_v3 ? s->data_bytes : s->total_docs);
682	        if (end <= start) continue;
683	        lens[t]     = end - start;   /* bytes for v3, docs for v2 */
684	        data_off[t] = s->data_base + (uint64_t)start * (is_v3 ? 1u : 4u);
685	        if (is_v3) total_bytes      += lens[t];
686	        else       total_docs_unit  += lens[t];
687	    }
688	
689	    /* Allocate read buffer:
690	       - SRT2: docs_buf sized to total_docs_unit
691	       - SRT3: bytes_buf sized to total_bytes; docs_buf sized to upper bound
692	
693	       Buffer storage selection : when g_use_shared_pool is on, all Forests
694	       in this thread share thread-local growable buffers — drops RAM 10×
695	       on multi-segment clusters since queries are serial anyway.          */
696	    uint8_t**  bytes_buf_ptr = g_use_shared_pool ? &g_shared_bytes_buf : &fm->bytes_buf;
697	    uint32_t*  bytes_cap_ptr = g_use_shared_pool ? &g_shared_bytes_cap : &fm->bytes_cap;
698	    uint32_t** docs_buf_ptr  = g_use_shared_pool ? &g_shared_docs_buf  : &fm->docs_buf;
699	    uint32_t*  docs_cap_ptr  = g_use_shared_pool ? &g_shared_docs_cap  : &fm->docs_cap;
700	    if (is_v3) {
701	        if ((uint64_t)*bytes_cap_ptr < total_bytes) {
702	            free(*bytes_buf_ptr);
703	            uint32_t new_cap = (uint32_t)(total_bytes + (total_bytes >> 1));
704	            if (new_cap < 1024) new_cap = 1024;
705	            *bytes_buf_ptr = (uint8_t*)malloc((size_t)new_cap);
706	            *bytes_cap_ptr = new_cap;
707	        }
708	        /* Each VarByte byte decodes ≤ 1 doc; first u32 contributes 1 doc per
709	           leaf. Upper bound on decoded docs = total_bytes (safe).            */
710	        if ((uint64_t)*docs_cap_ptr < total_bytes) {
711	            free(*docs_buf_ptr);
712	            uint32_t new_cap = (uint32_t)(total_bytes + (total_bytes >> 1));
713	            if (new_cap < 1024) new_cap = 1024;
714	            *docs_buf_ptr = (uint32_t*)malloc((size_t)new_cap * sizeof(uint32_t));
715	            *docs_cap_ptr = new_cap;
716	        }
717	    } else {
718	        if ((uint64_t)*docs_cap_ptr < total_docs_unit) {
719	            free(*docs_buf_ptr);
720	            uint32_t new_cap = (uint32_t)(total_docs_unit + (total_docs_unit >> 1));
721	            if (new_cap < 1024) new_cap = 1024;
722	            *docs_buf_ptr = (uint32_t*)malloc((size_t)new_cap * sizeof(uint32_t));
723	            *docs_cap_ptr = new_cap;
724	        }
725	    }
726	    uint32_t* docs  = *docs_buf_ptr;
727	    uint8_t*  bytes = *bytes_buf_ptr;
728	
729	    /* Phase 2: read posting lists (raw bytes for v3, uint32 array for v2). */
730	    int phase2_submits = 0;
731	    for (int t = 0; t < nt; t++) {
732	        if (lens[t] == 0) continue;
733	        void*    dst       = is_v3 ? (void*)(bytes + buf_pos[t])
734	                                   : (void*)(docs  + buf_pos[t]);
735	        unsigned nbytes    = is_v3 ? (unsigned)lens[t]
736	                                   : (unsigned)(lens[t] * 4u);
737	        if (f->ring_ok) {
738	            struct io_uring_sqe* sqe = io_uring_get_sqe(ring);
739	            if (!sqe) { io_uring_submit(ring); sqe = io_uring_get_sqe(ring); }
740	            io_uring_prep_read(sqe, f->stores[t].fd, dst, nbytes,
741	                               (uint64_t)data_off[t]);
742	            io_uring_sqe_set_data(sqe, (void*)(uintptr_t)t);
743	            phase2_submits++;
744	        } else {
745	            ssize_t pr2 = pread(f->stores[t].fd, dst, nbytes, (off_t)data_off[t]);
746	            (void)pr2;
747	        }
748	    }
749	    if (f->ring_ok) {
750	        io_uring_submit(ring);
751	        for (int r = 0; r < phase2_submits; r++) {
752	            struct io_uring_cqe* cqe;
753	            if (io_uring_wait_cqe(ring, &cqe) < 0) continue;
754	            io_uring_cqe_seen(ring, cqe);
755	        }
756	    }
757	
758	    /* SRT3: decode VarByte → uint32 docs. Iterates leaves in [i_lo, ...)
759	       until reaching high_leaf or window end. Updates buf_pos and lens to
760	       reflect decoded doc layout in docs[]. Falls through to legacy K-way
761	       merge with docs[buf_pos[t]..buf_pos[t]+lens[t]] sorted ascending.    */
762	    if (is_v3) {
763	        uint32_t cumulative = 0;
764	        for (int t = 0; t < nt; t++) {
765	            uint32_t byte_start_in_buf = buf_pos[t];
766	            uint32_t byte_len          = lens[t];
767	            buf_pos[t] = cumulative;
768	            lens[t]    = 0;
769	            if (byte_len == 0) continue;
770	
771	            const SortedStore* s = &f->stores[t];
772	            uint32_t low_leaf  = (uint32_t)leaves[t] << k_shift;
773	            uint32_t high_leaf = ((uint32_t)leaves[t] + 1u) << k_shift;
774	            const SparseEntry* low_w  = wbuf + ((size_t)t * 2 + 0) * window_n;
775	            const SparseEntry* high_w = wbuf + ((size_t)t * 2 + 1) * window_n;
776	            uint32_t low_len  = wlen[(size_t)t * 2 + 0];
777	            uint32_t high_len = wlen[(size_t)t * 2 + 1];
778	            uint32_t i_lo = lb_in_window(low_w,  low_len,  low_leaf);
779	            uint32_t i_hi = lb_in_window(high_w, high_len, high_leaf);
780	            if (i_lo >= low_len) continue;
781	            uint32_t slice_byte_start = low_w[i_lo].offset;
782	            uint32_t slice_byte_end   = (i_hi < high_len) ? high_w[i_hi].offset : s->data_bytes;
783	
784	            uint32_t k = i_lo;
785	            uint32_t out_n = 0;
786	            while (k < low_len) {
787	                uint32_t lstart_g = low_w[k].offset;
788	                if (lstart_g >= slice_byte_end) break;
789	                if (low_w[k].leaf_id >= high_leaf) break;
790	                uint32_t lend_g;
791	                if (k + 1 < low_len)
792	                    lend_g = low_w[k + 1].offset;
793	                else if (i_hi < high_len)
794	                    lend_g = high_w[i_hi].offset;
795	                else
796	                    lend_g = s->data_bytes;
797	                if (lend_g > slice_byte_end) lend_g = slice_byte_end;
798	                if (lend_g <= lstart_g) { k++; continue; }
799	
800	                uint32_t rel_start = lstart_g - slice_byte_start;
801	                uint32_t rel_end   = lend_g   - slice_byte_start;
802	                if (rel_start + 4 > rel_end) break;
803	                const uint8_t* slice = bytes + byte_start_in_buf;
804	                uint32_t first_doc;
805	                memcpy(&first_doc, slice + rel_start, 4);
806	                docs[cumulative + out_n++] = first_doc;
807	                uint32_t prev = first_doc;
808	                size_t bpos = rel_start + 4;
809	                while (bpos < rel_end) {
810	                    uint32_t delta = varbyte_decode_u32(slice, &bpos);
811	                    prev += delta;
812	                    docs[cumulative + out_n++] = prev;
813	                }
814	                k++;
815	            }
816	            lens[t]     = out_n;
817	            cumulative += out_n;
818	        }
819	    }
