821	    /* === No-filter fast path : radix sort + linear scan ===
822	       Replaces the per-tree qsort + K-way heap merge that follows for the
823	       case where allowed == NULL. Same semantics as the heap path: emit
824	       (doc, vote) where vote = number of trees containing the doc in this
825	       call. Critical for the C-multipass code path used by qd↓ queries —
826	       calling this function N_sets times with heap-merge was the bottleneck;
827	       radix collapses the K-way merge to O(N) sequential passes.            */
828	    if (allowed == NULL) {
829	        size_t N_total = 0;
830	        for (int t = 0; t < nt; t++) N_total += lens[t];
831	        if (N_total == 0) {
832	            g_last_n_distinct = 0;
833	            if (composed) roaring_bitmap_free(composed);
834	            return 0;
835	        }
836	        if (radix_ensure_cap(N_total) != 0) {
837	            if (composed) roaring_bitmap_free(composed);
838	            return -1;
839	        }
840	        uint64_t* pairs   = g_radix_pairs_buf;
841	        uint64_t* scratch = g_radix_scratch_buf;
842	        size_t cum = 0;
843	        for (int t = 0; t < nt; t++) {
844	            if (lens[t] == 0) continue;
845	            uint64_t tag = (uint64_t)t << 32;
846	            const uint32_t* src_t = docs + buf_pos[t];
847	            for (uint32_t i = 0; i < lens[t]; i++) {
848	                pairs[cum++] = tag | (uint64_t)src_t[i];
849	            }
850	        }
851	        /* 3-pass 11/11/10 radix sort on the low 32 bits (= the doc field).
852	           Mirrors the radix path of forest_collect_topn_probes. */
853	        uint64_t* src = pairs;
854	        uint64_t* dst = scratch;
855	        const int    BITS[3]   = {11, 11, 10};
856	        const int    SHIFTS[3] = {0, 11, 22};
857	        const uint32_t MASKS[3] = {0x7FFu, 0x7FFu, 0x3FFu};
858	        for (int pass = 0; pass < 3; pass++) {
859	            int n_buckets = 1 << BITS[pass];
860	            int shift     = SHIFTS[pass];
861	            uint32_t mask = MASKS[pass];
862	            uint32_t hist [2048] = {0};
863	            uint32_t hist1[2048] = {0};
864	            uint32_t hist2[2048] = {0};
865	            uint32_t hist3[2048] = {0};
866	            size_t i = 0;
867	            for (; i + 4 <= N_total; i += 4) {
868	                hist [(src[i+0] >> shift) & mask]++;
869	                hist1[(src[i+1] >> shift) & mask]++;
870	                hist2[(src[i+2] >> shift) & mask]++;
871	                hist3[(src[i+3] >> shift) & mask]++;
872	            }
873	            for (; i < N_total; i++) hist[(src[i] >> shift) & mask]++;
874	            for (int b = 0; b < n_buckets; b++)
875	                hist[b] += hist1[b] + hist2[b] + hist3[b];
876	            uint32_t acc = 0;
877	            for (int b = 0; b < n_buckets; b++) {
878	                uint32_t c = hist[b];

1036	int forest_collect_topn_probes(const Forest* f,
1037	                               const int32_t* leaves, int n_sets,
1038	                               int top_n, int probe_depth,
1039	                               const roaring_bitmap_t* allowed_in,
1040	                               int32_t* out_ids, int32_t* out_votes) {
1041	    if (top_n <= 0 || n_sets <= 0) return 0;
1042	    int nt = f->n_trees;
1043	    int is_v3 = (f->srt_version == 3);
1044	    /* probe_depth ≤ 0 or ≥ depth → native (k_shift=0, fast path).
1045	       Else each probe-leaf at probe_depth covers 2^k_shift storage leaves. */
1046	    int qd_eff = (probe_depth > 0 && probe_depth < (int)f->depth)
1047	                 ? probe_depth : (int)f->depth;
1048	    int k_shift = (int)f->depth - qd_eff;
1049	
1050	    /* Compose effective filter with tombstones (same policy as collect_topn). */
1051	    const roaring_bitmap_t* allowed = allowed_in;
1052	    roaring_bitmap_t* composed = NULL;
1053	    if (f->tombstones && roaring_bitmap_get_cardinality(f->tombstones) > 0) {
1054	        composed = allowed_in
1055	                 ? roaring_bitmap_andnot(allowed_in, f->tombstones)
1056	                 : roaring_bitmap_flip(f->tombstones, 0, (uint64_t)f->n_docs);
1057	        allowed = composed;
1058	    }
1059	
1060	    size_t nL = (size_t)nt * (size_t)n_sets;   /* total leaf-cursors */
1061	    Forest* fm = (Forest*)f;
1062	    struct io_uring* ring = (struct io_uring*)&f->ring;
1063	    uint32_t window_n = fm->max_window_n;
1064	
1065	    /* Per-leaf scratch (allocated per call; nL ~ a few thousand, cheap). */
1066	    SparseEntry* wbuf = (SparseEntry*)malloc(nL * 2 * window_n * sizeof(SparseEntry));
1067	    uint32_t* wlen     = (uint32_t*)malloc(nL * 2 * sizeof(uint32_t));
1068	    uint64_t* doff     = (uint64_t*)malloc(nL * sizeof(uint64_t));
1069	    uint32_t* lens     = (uint32_t*)malloc(nL * sizeof(uint32_t));
1070	    uint32_t* bpos     = (uint32_t*)malloc(nL * sizeof(uint32_t));
1071	    int32_t*  leaf_tree= (int32_t*) malloc(nL * sizeof(int32_t));
1072	    if (!wbuf || !wlen || !doff || !lens || !bpos || !leaf_tree) {
1073	        free(wbuf); free(wlen); free(doff); free(lens); free(bpos); free(leaf_tree);
1074	        if (composed) roaring_bitmap_free(composed);
1075	        return -1;
1076	    }
1077	
1078	    /* Phase 1: read sparse_index windows around the probe leaf.
1079	       k_shift = 0 (native depth) → 1 window per (s, t) for the target leaf.
1080	       k_shift > 0 → 2 windows per (s, t) : one around low_leaf (first
1081	       storage leaf of the subtree), one around high_leaf (one past the
1082	       last). Both windows are needed because they may live in different
1083	       sample buckets when the subtree spans a bucket boundary.
1084	
1085	       Storage: wbuf + (li*2 + slot) * window_n,  wlen[li*2 + slot]. */
1086	    int slots_to_read = (k_shift > 0) ? 2 : 1;
1087	    int p1 = 0;
1088	    for (int s = 0; s < n_sets; s++) {
1089	        for (int t = 0; t < nt; t++) {
1090	            size_t li = (size_t)s * nt + t;
1091	            leaf_tree[li] = t;
1092	            wlen[li * 2 + 0] = 0;
1093	            wlen[li * 2 + 1] = 0;
1094	            const SortedStore* st = &f->stores[t];
1095	            int32_t lf = leaves[(size_t)s * nt + t];
1096	            if (lf < 0 || st->n_nonempty == 0) continue;
1097	            uint32_t low_leaf  = (k_shift > 0) ? ((uint32_t)lf << k_shift) : (uint32_t)lf;
1098	            uint32_t high_leaf = (k_shift > 0) ? (((uint32_t)lf + 1u) << k_shift) : ((uint32_t)lf + 1u);
