300	        f->fixed_buf = NULL; f->fixed_buf_size = 0;
301	    }
302	    if (f->stores) {
303	        for (int t = 0; t < f->n_trees; t++) sorted_store_close(&f->stores[t]);
304	        free(f->stores); f->stores = NULL;
305	    }
306	    free(f->wbuf);         f->wbuf         = NULL;
307	    free(f->wlen_buf);     f->wlen_buf     = NULL;
308	    free(f->woff_buf);     f->woff_buf     = NULL;
309	    free(f->leaves_buf);   f->leaves_buf   = NULL;
310	    free(f->lens_buf);     f->lens_buf     = NULL;
311	    free(f->data_off_buf); f->data_off_buf = NULL;
312	    free(f->buf_pos_buf);  f->buf_pos_buf  = NULL;
313	    free(f->cursors_buf);  f->cursors_buf  = NULL;
314	    free(f->heap_buf);     f->heap_buf     = NULL;
315	    free(f->topn_h_buf);    f->topn_h_buf    = NULL;
