141	            fv = tmpf;
142	        } else {
143	            fv = (const float*)(raw + (size_t)idx * row_bytes);
144	        }
145	        float d = l2sq(qvec, fv, dim);
146	        int32_t id = cand_ids[idx];
147	
148	        if (heap_n < k) {
149	            heap[heap_n].d = d; heap[heap_n].id = id;
150	            heap_n++;
151	            if (heap_n == k)
152	                for (int j = k/2 - 1; j >= 0; j--) heap_sift_down(heap, k, j);
153	        } else if (d < heap[0].d) {
154	            heap[0].d = d; heap[0].id = id;
155	            heap_sift_down(heap, k, 0);
156	        }
157	    }
158	
159	    qsort(heap, (size_t)k, sizeof(DistId), cmp_distid);
160	    for (int i = 0; i < k; i++) out_ids[i] = heap[i].id;
161	
162	    free(heap); free(raw);
163	    return k;
164	}
