166	int rerank_l2(int base_fd, VecFmt base_fmt, int dim, const float* qvec,
167	              const int32_t* cand_ids, int n_cands,
168	              int top_k, int32_t* out_ids) {
169	    if (n_cands <= 0) return 0;
170	    int k = (top_k < n_cands) ? top_k : n_cands;
171	
172	    DistId* heap = (DistId*)malloc((size_t)k * sizeof(DistId));
173	    float*  cv   = (float*) malloc((size_t)dim * sizeof(float));
174	    if (!heap || !cv) { free(heap); free(cv); return -1; }
175	
176	    for (int i = 0; i < k; i++) {
177	        if (read_vec_at(base_fd, base_fmt, cand_ids[i], dim, cv) != 0) {
178	            heap[i].d = INFINITY; heap[i].id = cand_ids[i]; continue;
179	        }
180	        heap[i].d  = l2sq(qvec, cv, dim);
181	        heap[i].id = cand_ids[i];
182	    }
183	    for (int i = k/2 - 1; i >= 0; i--) heap_sift_down(heap, k, i);
184	
185	    for (int i = k; i < n_cands; i++) {
186	        if (read_vec_at(base_fd, base_fmt, cand_ids[i], dim, cv) != 0) continue;
187	        float d = l2sq(qvec, cv, dim);
188	        if (d < heap[0].d) {
189	            heap[0].d  = d;
190	            heap[0].id = cand_ids[i];
191	            heap_sift_down(heap, k, 0);
192	        }
193	    }
194	
195	    qsort(heap, (size_t)k, sizeof(DistId), cmp_distid);
196	    for (int i = 0; i < k; i++) out_ids[i] = heap[i].id;
197	
198	    free(heap); free(cv);
199	    return k;
200	}
