202	int eval_recall(Forest* f,
203	                const char* qvecs_path, const char* gt_path,
204	                const char* base_path,
205	                int n_queries, int top_k, int threshold,
206	                int max_cands,
207	                double* out_recall, double* out_avg_cands,
208	                double* out_ms_per_query) {
209	    int dim = f->dim;
210	    VecFmt qfmt = vec_fmt_from_path(qvecs_path);
211	    VecFmt bfmt = vec_fmt_from_path(base_path);
212	
213	    int qfd = open(qvecs_path,   O_RDONLY);
214	    int gfd = open(gt_path,      O_RDONLY);
215	    int bfd = open(base_path,    O_RDONLY);
216	    if (qfd < 0 || gfd < 0 || bfd < 0) {
217	        perror("open"); return -1;
218	    }
219	    /* GT_K from the ivecs file header (first int32). Default 100 if read fails. */
220	    int GT_K = 100;
221	    {
222	        int hdr;
223	        if (pread(gfd, &hdr, 4, 0) == 4 && hdr > 0 && hdr <= 10000) GT_K = hdr;
224	    }
225	
226	    /* Buffers reused across queries. */
227	    float*    qvec      = (float*)   malloc((size_t)dim * 4);
228	    uint16_t* votes     = (uint16_t*)malloc((size_t)f->n_docs * sizeof(uint16_t));
229	    int32_t*  cand_ids  = (int32_t*) malloc((size_t)max_cands * 4);
230	    int32_t*  cand_vot  = (int32_t*) malloc((size_t)max_cands * 4);
231	    int32_t*  top_ids   = (int32_t*) malloc((size_t)top_k * 4);
232	    int*      gt        = (int*)     malloc((size_t)GT_K * 4);
233	
234	    if (!qvec || !votes || !cand_ids || !cand_vot || !top_ids || !gt) {
235	        fprintf(stderr, "alloc failed\n"); return -1;
236	    }
237	
238	    long long hits = 0, total_cands = 0;
239	    double t0 = now_s();
240	
241	    for (int q = 0; q < n_queries; q++) {
242	        if (read_vec_at(qfd, qfmt, q, dim, qvec) != 0) { n_queries = q; break; }
243	        if (read_ivec(gfd, q, GT_K, gt) != 0)          { n_queries = q; break; }
244	
245	        int n_c = forest_collect(f, qvec, threshold, max_cands,
246	                                 cand_ids, cand_vot, votes);
247	        total_cands += n_c;
248	
249	        int n_top = rerank_l2(bfd, bfmt, dim, qvec, cand_ids, n_c, top_k, top_ids);
250	
251	        /* Count how many of our top_k are in groundtruth's top_k. */
252	        for (int i = 0; i < n_top; i++) {
253	            int id = top_ids[i];
254	            for (int j = 0; j < top_k && j < GT_K; j++)
255	                if (gt[j] == id) { hits++; break; }
256	        }
257	
258	        if ((q + 1) % 100 == 0 || q + 1 == n_queries) {
259	            double dt = now_s() - t0;
260	            fprintf(stderr,
261	                "  q=%4d/%d  recall@%d=%.4f  avg_cands=%.0f  %.1f ms/q  rss=%ld KB\n",
262	                q + 1, n_queries, top_k,
263	                (double)hits / ((q + 1) * (double)top_k),
264	                (double)total_cands / (q + 1),
265	                dt * 1000.0 / (q + 1),
266	                peak_rss_kb());
267	        }
268	    }
269	
270	    double dt = now_s() - t0;
271	    *out_recall       = (double)hits / ((double)n_queries * top_k);
272	    *out_avg_cands    = (double)total_cands / n_queries;
273	    *out_ms_per_query = dt * 1000.0 / n_queries;

296	int traverse_sub_probes_scored(const float* vec, int full_dim, int sub_dim, int depth,
297	                               uint64_t ts, float* v0, float* v1, int* dims,
298	                               int n_probes, int min_flip_level,
299	                               int32_t* out_nodes, float* out_scores) {
300	    int32_t other_child[64];
301	    float   margin[64];
302	    char    used[64];
303	    if (depth > 64) depth = 64;
304	    if (min_flip_level < 0) min_flip_level = 0;
305	    if (min_flip_level >= depth) min_flip_level = depth > 0 ? depth - 1 : 0;
306	
307	    int active = (g_tree_sub > 0 && g_tree_sub < full_dim);
308	    int   td  [active ? g_tree_sub : 1];
309	    float vsub[active ? g_tree_sub : 1];
310	    if (active) {
311	        pick_tree_dims(tree_sub_seed(ts), full_dim, g_tree_sub, td);
312	        for (int i = 0; i < g_tree_sub; i++) vsub[i] = vec[td[i]];
313	        vec = vsub; full_dim = g_tree_sub;
314	    }
315	
316	    int32_t node = 0;
317	    float min_main = 0.0f;
318	    for (int level = 0; level < depth; level++) {
319	        pick_dims(ts, node, full_dim, sub_dim, dims);
320	        gen_vec(node_seed(ts, node * 2),     v0, sub_dim);
321	        gen_vec(node_seed(ts, node * 2 + 1), v1, sub_dim);
322	        float c0 = dot_sub(vec, v0, dims, sub_dim);
323	        float c1 = dot_sub(vec, v1, dims, sub_dim);
324	        int32_t chosen, other;
325	        if (c1 > c0) { chosen = 2 * node + 2; other = 2 * node + 1; }
326	        else         { chosen = 2 * node + 1; other = 2 * node + 2; }
327	        other_child[level] = other;
328	        margin[level]      = fabsf(c1 - c0);
329	        used[level]        = 0;
330	        if (level == 0 || margin[level] < min_main) min_main = margin[level];
331	        node = chosen;
332	    }
333	    out_nodes[0]  = node;
334	    out_scores[0] = min_main;
335	    int count = 1;
336	    int eligible = depth - min_flip_level;
337	    if (n_probes > eligible) n_probes = eligible;
338	
339	    /* Per-probe : flip the smallest-margin level among unused, retraverse the
340	       remainder of the tree from the sibling, and compute that path's min
341	       margin too. */
342	    float vp0[1024], vp1[1024]; int pdims[256];
343	    (void)vp0; (void)vp1; (void)pdims;  /* unused if depth small */
344	    for (int p = 0; p < n_probes; p++) {
345	        int best = -1; float bm = 0.0f;
346	        for (int level = min_flip_level; level < depth; level++) {
347	            if (used[level]) continue;
348	            if (best < 0 || margin[level] < bm) { best = level; bm = margin[level]; }
349	        }
350	        if (best < 0) break;
351	        used[best] = 1;
352	
353	        /* min margin BEFORE the flip (levels 0..best-1, from the main path). */
354	        float min_kept = (best == 0) ? margin[best] : margin[0];
355	        for (int j = 1; j < best; j++)
356	            if (margin[j] < min_kept) min_kept = margin[j];
357	        if (best > 0 && margin[best] < min_kept) min_kept = margin[best];
358	        /* margin[best] is itself a "decision margin" the probe takes (flipped),
359	           so include it too. */
360	
361	        /* Continuation from sibling, computing margins as we go. */
362	        int32_t cnode = other_child[best];
363	        float min_post = INFINITY;
364	        for (int level = best + 1; level < depth; level++) {
365	            pick_dims(ts, cnode, full_dim, sub_dim, dims);
366	            gen_vec(node_seed(ts, cnode * 2),     v0, sub_dim);
367	            gen_vec(node_seed(ts, cnode * 2 + 1), v1, sub_dim);
368	            float c0 = dot_sub(vec, v0, dims, sub_dim);
369	            float c1 = dot_sub(vec, v1, dims, sub_dim);
370	            float mm = fabsf(c1 - c0);
371	            if (mm < min_post) min_post = mm;
372	            cnode = (c1 > c0) ? 2*cnode + 2 : 2*cnode + 1;
373	        }
374	        out_nodes[count]  = cnode;
375	        out_scores[count] = (min_post < min_kept) ? min_post : min_kept;
376	        count++;
377	    }
378	    return count;
379	}
