381	int traverse_sub_probes(const float* vec, int full_dim, int sub_dim, int depth,
382	                        uint64_t ts, float* v0, float* v1, int* dims,
383	                        int n_probes, int min_flip_level, int32_t* out_nodes) {
384	    int32_t other_child[64];
385	    float   margin[64];
386	    char    used[64];
387	    if (depth > 64) depth = 64;
388	    if (min_flip_level < 0) min_flip_level = 0;
389	    if (min_flip_level >= depth) min_flip_level = depth > 0 ? depth - 1 : 0;
390	
391	    int active = (g_tree_sub > 0 && g_tree_sub < full_dim);
392	    int   td  [active ? g_tree_sub : 1];
393	    float vsub[active ? g_tree_sub : 1];
394	    if (active) {
395	        pick_tree_dims(tree_sub_seed(ts), full_dim, g_tree_sub, td);
396	        for (int i = 0; i < g_tree_sub; i++) vsub[i] = vec[td[i]];
397	        vec = vsub; full_dim = g_tree_sub;   /* continue calls inherit this */
398	    }
399	
400	    int32_t node = 0;
401	    for (int level = 0; level < depth; level++) {
402	        pick_dims(ts, node, full_dim, sub_dim, dims);
403	        gen_vec(node_seed(ts, node * 2),     v0, sub_dim);
404	        gen_vec(node_seed(ts, node * 2 + 1), v1, sub_dim);
405	        float c0 = dot_sub(vec, v0, dims, sub_dim);
406	        float c1 = dot_sub(vec, v1, dims, sub_dim);
407	        int32_t chosen, other;
408	        if (c1 > c0) { chosen = 2 * node + 2; other = 2 * node + 1; }
409	        else         { chosen = 2 * node + 1; other = 2 * node + 2; }
410	        other_child[level] = other;
411	        margin[level]      = fabsf(c1 - c0);
412	        used[level]        = 0;
413	        node = chosen;
414	    }
415	    out_nodes[0] = node;
416	    int count = 1;
417	    int eligible = depth - min_flip_level;          /* # flippable levels */
418	    if (n_probes > eligible) n_probes = eligible;
419	    for (int p = 0; p < n_probes; p++) {
420	        int best = -1; float bm = 0.0f;
421	        for (int level = min_flip_level; level < depth; level++) {
422	            if (used[level]) continue;
423	            if (best < 0 || margin[level] < bm) { best = level; bm = margin[level]; }
424	        }
425	        if (best < 0) break;
426	        used[best] = 1;
427	        out_nodes[count++] = traverse_sub_continue(
428	            vec, full_dim, sub_dim, best + 1, depth - best - 1,
429	            other_child[best], ts, v0, v1, dims);
430	    }
431	    return count;
432	}
